insert into platform.applications (application_key,name,description,is_core,launcher_path) values ('CUSTOMER_ADMIN','Customer Admin','Organization administration',true,'/admin'),('REAL_ESTATE','Hakika Real Estate','Rental and property operations',false,'/real-estate'),('HR','HR','Workforce operations',false,'/hr'),('FINANCE','Finance','Finance and accounting',false,'/finance'),('TOUGHFORCE','ToughForce Security','Security workforce operations',false,'/toughforce'),('PLATFORM_ADMIN','Platform Admin','Hakika platform operations',true,'/platform') on conflict (application_key) do nothing;
insert into iam.pages (application_id,page_key,route_pattern,name,nav_group,nav_order) select a.id,v.page_key,v.route_pattern,v.name,v.nav_group,v.nav_order from platform.applications a cross join (values ('dashboard','/dashboard','Dashboard','Overview',0),('settings','/settings','Settings','Configuration',90)) as v(page_key,route_pattern,name,nav_group,nav_order) where a.application_key in ('REAL_ESTATE','HR','FINANCE','TOUGHFORCE','CUSTOMER_ADMIN','PLATFORM_ADMIN') on conflict (application_id,page_key) do nothing;
insert into iam.roles (role_key,name,scope,is_system,is_read_only) values ('platform_admin','Platform Admin','platform',true,false),('customer_admin','Customer Admin','organization',true,false),('viewer','Read-only viewer','application',true,true) on conflict do nothing;
insert into iam.permissions (permission_key,action,description) values ('admin.members.read','read','Read organization members'),('admin.members.invite','manage','Invite and assign organization members'),('admin.roles.read','read','Read organization roles'),('admin.audit.read','read','Read organization audit events'),('platform.audit.read','read','Read platform-wide audit events'),('real_estate.properties.read','read','Read scoped properties'),('real_estate.units.read','read','Read scoped units'),('real_estate.tenants.read','read','Read scoped tenants'),('real_estate.landlords.read','read','Read scoped landlords'),('real_estate.caretakers.read','read','Read scoped caretakers'),('real_estate.leases.read','read','Read scoped leases'),('real_estate.billing.read','read','Read scoped billing runs'),('real_estate.invoices.read','read','Read scoped invoices'),('real_estate.payments.read','read','Read scoped payments'),('real_estate.payments.create','create','Record scoped payments'),('real_estate.mpesa.read','read','Read scoped M-Pesa transactions'),('real_estate.payouts.read','read','Read scoped payout jobs'),('real_estate.payouts.approve','approve','Approve scoped payout allocations'),('real_estate.tenant_portal.preview','preview_portal','Preview a portal read-only'),('real_estate.properties.create','create','Create scoped properties'),('real_estate.properties.update','update','Update scoped properties') on conflict (permission_key) do nothing;
